/**
 * Ember's motion system: one vocabulary of curves, springs and entrances for
 * the whole app, in JS (Framer Motion) and in CSS (globals.css carries the
 * same springs as `linear()` easings, generated by springCss below).
 *
 * The rules it encodes:
 *
 *  • Things that move are springs; things that only change (colour, opacity)
 *    are short eased tweens. A spring keeps its velocity when it is
 *    interrupted, which is what makes a UI feel held rather than played back.
 *  • Springs are described the way they are perceived (how long, how much
 *    bounce) and resolved to physics here, so no component invents its own
 *    stiffness and damping.
 *  • Leaving is quicker than arriving, and accelerates away.
 *  • Opacity leads, position follows: a fade is over in roughly half the time
 *    the movement takes, so nothing is see-through while it settles.
 *  • Glass never fades under a fading parent. An ancestor with opacity below 1
 *    is a backdrop root: every pane inside loses its frosting until the fade
 *    ends. Panes enter by moving (transform); only floating chrome fades, and
 *    then on its own element.
 */

/** Easing curves. `out` is the house curve: fast start, long soft settle. */
export const EASE = {
  out: [0.22, 1, 0.36, 1],
  inOut: [0.65, 0, 0.35, 1],
  /** exits: accelerate away, never linger */
  in: [0.4, 0, 1, 1],
  entrance: [0.16, 1, 0.3, 1],
} as const;

/** Durations in seconds, for tweens (colour, opacity) only. */
export const DURATION = {
  instant: 0.1,
  fast: 0.16,
  base: 0.24,
  slow: 0.36,
  slower: 0.6,
  ambient: 1.1,
} as const;

export interface SpringPhysics {
  type: "spring";
  stiffness: number;
  damping: number;
  mass: number;
}

/**
 * A spring from how it is perceived: `duration` is how long it takes to look
 * settled (seconds), `bounce` 0 is critically damped (no overshoot), 0.3 a
 * visible but polite bounce. Mass is 1.
 *
 * Resolved to stiffness/damping on purpose. Framer Motion's own
 * duration-based springs drop the velocity an interrupted animation was
 * carrying; physical ones keep it.
 */
export function spring(duration: number, bounce = 0): SpringPhysics {
  const omega = (2 * Math.PI) / duration;
  const zeta = Math.min(1, Math.max(0.05, 1 - bounce));
  return { type: "spring", stiffness: omega * omega, damping: 2 * zeta * omega, mass: 1 };
}

/** The spring vocabulary, as [perceived duration, bounce]. */
export const SPRING_SPEC = {
  /** controls: toggles, tab pills, selection, press release */
  snappy: [0.26, 0.14],
  /** surfaces: dialogs, popovers, cards, rows changing height */
  smooth: [0.36, 0],
  /** large or heavy things: sheets, page blocks, hero elements */
  gentle: [0.52, 0],
  /** celebration and confirmation only: ticks, badges, the milestone mark */
  bouncy: [0.42, 0.3],
  /** data settling: rings, bars, charts */
  fill: [0.9, 0],
} as const;

export type SpringName = keyof typeof SPRING_SPEC;

export const SPRING = {
  snappy: spring(...SPRING_SPEC.snappy),
  smooth: spring(...SPRING_SPEC.smooth),
  gentle: spring(...SPRING_SPEC.gentle),
  bouncy: spring(...SPRING_SPEC.bouncy),
  fill: spring(...SPRING_SPEC.fill),
} as const satisfies Record<SpringName, SpringPhysics>;

/** position of a unit spring (0 → 1, released at rest) at time t seconds */
export function springValue(s: SpringPhysics, t: number): number {
  if (t <= 0) return 0;
  const omega = Math.sqrt(s.stiffness / s.mass);
  const zeta = s.damping / (2 * Math.sqrt(s.stiffness * s.mass));
  if (zeta >= 1) return 1 - Math.exp(-omega * t) * (1 + omega * t);
  const wd = omega * Math.sqrt(1 - zeta * zeta);
  return 1 - Math.exp(-zeta * omega * t) * (Math.cos(wd * t) + ((zeta * omega) / wd) * Math.sin(wd * t));
}

/** ms after which a unit spring stays within `tolerance` of its target */
export function springSettleMs(s: SpringPhysics, tolerance = 0.001): number {
  let last = 0;
  for (let ms = 0; ms <= 4000; ms++) {
    if (Math.abs(1 - springValue(s, ms / 1000)) > tolerance) last = ms;
  }
  return Math.ceil((last + 1) / 10) * 10;
}

/**
 * The same spring for CSS: a duration and a `linear()` easing that samples
 * the spring's curve. globals.css holds the output for every entry of
 * SPRING_SPEC (a test keeps the two in step), so a CSS hover and a Framer
 * dialog move on the same physics.
 */
export function springCss(name: SpringName): { ms: number; easing: string } {
  const s = SPRING[name];
  const ms = springSettleMs(s);
  const points = Math.min(48, Math.max(16, Math.round(ms / 16)));
  const stops: string[] = [];
  for (let i = 0; i <= points; i++) {
    const v = i === 0 ? 0 : i === points ? 1 : springValue(s, ((i / points) * ms) / 1000);
    stops.push(String(Number(v.toFixed(4))));
  }
  return { ms, easing: `linear(${stops.join(", ")})` };
}

/* ---- tweens ------------------------------------------------------------ */

/** the fade that accompanies a spring: over well before the movement is */
const LEAD_FADE = { duration: DURATION.fast, ease: EASE.out };
/** how things leave */
export const EXIT = { duration: 0.14, ease: EASE.in } as const;

/** a spring for the movement with the fade leading it */
export const withFade = (s: SpringPhysics, delay = 0) => ({ ...s, delay, opacity: { ...LEAD_FADE, delay } });

/**
 * Delay for item `i` of a cascade. Tight (34 ms) and capped: the tenth row
 * must not arrive a third of a second after the first.
 */
export const staggerDelay = (i: number, each = 0.034, cap = 8) => Math.min(Math.max(0, i), cap) * each;

/* ---- entrances and exits -----------------------------------------------
   Spread onto a motion element: <motion.div {...dialog} />. Each carries its
   own transitions, so arriving and leaving differ without the caller saying
   so. `initial={false}` on the element still works as usual.              */

/** plain fade: text swaps, overlays without a shape */
export const fade = {
  initial: { opacity: 0 },
  animate: { opacity: 1, transition: { duration: DURATION.base, ease: EASE.out } },
  exit: { opacity: 0, transition: EXIT },
} as const;

/** content swapped in place (edit ↔ preview, one step of a form for the next): out and in, quickly */
export const swap = {
  initial: { opacity: 0 },
  animate: { opacity: 1, transition: { duration: DURATION.instant, ease: EASE.out } },
  exit: { opacity: 0, transition: { duration: DURATION.instant, ease: EASE.in } },
} as const;

/** the dimming layer behind a dialog or sheet */
export const scrim = {
  initial: { opacity: 0 },
  animate: { opacity: 1, transition: { duration: DURATION.base, ease: EASE.out } },
  exit: { opacity: 0, transition: { duration: DURATION.fast, ease: EASE.in } },
} as const;

/** a centred dialog: grows the last few percent into place */
export const dialog = {
  initial: { opacity: 0, scale: 0.94, y: 14 },
  animate: { opacity: 1, scale: 1, y: 0, transition: withFade(SPRING.smooth) },
  exit: { opacity: 0, scale: 0.97, y: 6, transition: EXIT },
} as const;

/** a bottom sheet: rides up from the edge, opaque the whole way */
export const sheet = {
  initial: { y: "100%" },
  animate: { y: 0, transition: SPRING.smooth },
  exit: { y: "100%", transition: { duration: DURATION.base, ease: EASE.in } },
} as const;

/** menus, popovers, tooltips: scale out of the thing that opened them */
export const pop = {
  initial: { opacity: 0, scale: 0.95 },
  animate: { opacity: 1, scale: 1, transition: { ...SPRING.snappy, opacity: { duration: DURATION.instant, ease: EASE.out } } },
  exit: { opacity: 0, scale: 0.97, transition: { duration: DURATION.instant, ease: EASE.in } },
} as const;

/** toasts, pills, banners: a short rise (negative `from` drops in from above) */
export const rise = (from = 14) =>
  ({
    initial: { opacity: 0, y: from, scale: 0.96 },
    animate: { opacity: 1, y: 0, scale: 1, transition: withFade(SPRING.snappy) },
    exit: { opacity: 0, y: from / 2, scale: 0.97, transition: EXIT },
  }) as const;

/** content inside a pane (never the pane itself): fades up, cascading by index */
export const item = (i = 0, from = 8) =>
  ({
    initial: { opacity: 0, y: from },
    animate: { opacity: 1, y: 0, transition: withFade(SPRING.smooth, staggerDelay(i)) },
  }) as const;

/** a list row arriving and leaving: opens its own height, closes it again */
export const row = {
  initial: { opacity: 0, height: 0 },
  animate: { opacity: 1, height: "auto", transition: withFade(SPRING.smooth) },
  exit: { opacity: 0, height: 0, transition: { ...SPRING.smooth, opacity: { duration: DURATION.instant, ease: EASE.in } } },
} as const;

/**
 * A glass card joining a list once the page is up (a new goal, a new habit):
 * it grows into place and never fades in, because the fade would have to sit
 * on a wrapper and a fading wrapper strips the frosting off the pane inside.
 * Leaving may fade: the pane is going anyway. Use with AnimatePresence
 * initial={false}; the page entrance itself is the CSS cascade.
 */
export const card = {
  initial: { scale: 0.94, y: 12 },
  animate: { scale: 1, y: 0, transition: SPRING.smooth },
  exit: { opacity: 0, scale: 0.96, transition: EXIT },
} as const;

/** tiles in a grid (files, media): scale in and out in place */
export const tile = {
  initial: { opacity: 0, scale: 0.92 },
  animate: { opacity: 1, scale: 1, transition: withFade(SPRING.snappy) },
  exit: { opacity: 0, scale: 0.92, transition: EXIT },
} as const;

/** a mark that confirms something: tick badge, selected dot */
export const stamp = {
  initial: { scale: 0 },
  animate: { scale: 1, transition: SPRING.bouncy },
} as const;

/** the pulse a checkbox gives as it takes */
export const CHECK_PULSE: { animate: { scale: number[] }; transition: { duration: number; ease: typeof EASE.out; times: number[] } } = {
  animate: { scale: [1, 1.24, 1] },
  transition: { duration: 0.38, ease: EASE.out, times: [0, 0.4, 1] },
};

/** the stroke of a tick being drawn */
export const TICK_DRAW = { duration: 0.28, delay: 0.04, ease: EASE.inOut } as const;

/** "no": a short horizontal shake for a rejected input */
export const SHAKE: { animate: { x: number[] }; transition: { duration: number; ease: typeof EASE.out } } = {
  animate: { x: [0, -8, 8, -5, 5, 0] },
  transition: { duration: 0.4, ease: EASE.out },
};

/**
 * Particle / energy colours.
 *
 * These are CSS custom properties, not literals, so every burst automatically
 * inherits the active theme — sunset, tide, crimson or orchid. Nothing here
 * may ever be a hardcoded hex, otherwise the effects go on looking "orange"
 * in a blue theme.
 */
export const THEME_PARTICLES = [
  "var(--sunset-from)",
  "var(--sunset-to)",
  "var(--primary-bright)",
  "var(--accent)",
] as const;
